import React, { Component } from 'react';
import { CButton, CCol, CContainer, CRow } from '@coreui/react';
import { requestHeaderGETWithAuth, requestHeaderPOSTWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';
import Select from 'react-select';

const FILE_NAME = "WeeklyHeatmap.js";

function getMonday(dateStr) {
    const d = new Date(dateStr + 'T00:00:00');
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    d.setDate(diff);
    const yyyy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');
    return `${yyyy}-${mm}-${dd}`;
}

function getWeekDates(mondayStr) {
    const dates = [];
    for (let i = 0; i < 7; i++) {
        const d = new Date(mondayStr + 'T00:00:00');
        d.setDate(d.getDate() + i);
        const yyyy = d.getFullYear();
        const mm = String(d.getMonth() + 1).padStart(2, '0');
        const dd = String(d.getDate()).padStart(2, '0');
        dates.push(`${yyyy}-${mm}-${dd}`);
    }
    return dates;
}

function getTodayDate() {
    const d = new Date();
    const yyyy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');
    return `${yyyy}-${mm}-${dd}`;
}

function formatDate(dateStr) {
    const d = new Date(dateStr + 'T00:00:00');
    return d.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
}

const DAY_LABELS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

class WeeklyHeatmap extends Component {

    constructor(props) {
        super(props);
        this.state = {
            weekStart: getMonday(getTodayDate()),
            subPrograms: [],
            programs: [],
            selectedSubProgramId: '',
            programTypeFilter: localStorage.getItem('heatmapTypeFilter') || '',
            weekData: {}, // { date: [timeLogs] }
            isLoaded: false,
            isLoadingWeek: false,
            error: null,
        };
    }

    componentDidMount() {
        document.title = "Weekly Heatmap";
        this.fetchReferenceData().then(() => this.fetchWeekData());
    }

    fetchReferenceData = () => {
        const userData = getUserDataFromLocalStorage();
        const subProgramPayload = JSON.stringify({ size: 0 });
        const programPayload = JSON.stringify({ size: 0 });

        return Promise.all([
            fetch(BACKEND_NEXUS_APP_BASE_URL + '/v1/sub-program/list', requestHeaderPOSTWithAuth(subProgramPayload, userData.authToken)).then(r => r.status === 200 ? r.json() : null),
            fetch(BACKEND_NEXUS_APP_BASE_URL + '/v1/program/list', requestHeaderPOSTWithAuth(programPayload, userData.authToken)).then(r => r.status === 200 ? r.json() : null),
        ])
        .then(([subProgramsResult, programsResult]) => {
            this.setState({
                subPrograms: (subProgramsResult && subProgramsResult.data) || [],
                programs: (programsResult && programsResult.data) || [],
                isLoaded: true,
            });
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchReferenceData", "ERROR", "error", error);
            this.setState({ isLoaded: true, error: error.message });
        });
    }

    fetchWeekData = () => {
        const { weekStart } = this.state;
        const weekDates = getWeekDates(weekStart);
        const userData = getUserDataFromLocalStorage();

        this.setState({ isLoadingWeek: true });

        const fetchDay = (date) =>
            fetch(BACKEND_NEXUS_APP_BASE_URL + '/v1/time-log/day?date=' + date, requestHeaderGETWithAuth(userData.authToken))
                .then(response => {
                    if (response.status === 200) return response.json();
                    if (response.status === 401) { logoutProcedureForLocalStorage(); reloadPage(); }
                    throw new Error("HTTP " + response.status);
                })
                .then(result => ({ date, logs: result.data || [] }))
                .catch(() => ({ date, logs: [] }));

        Promise.all(weekDates.map(fetchDay))
            .then(results => {
                const weekData = {};
                results.forEach(r => { weekData[r.date] = r.logs; });
                this.setState({ weekData, isLoadingWeek: false });
            })
            .catch(error => {
                Logger(FILE_NAME, "fetchWeekData", "ERROR", "error", error);
                this.setState({ isLoadingWeek: false, error: error.message });
            });
    }

    onWeekChange = (offset) => {
        const { weekStart } = this.state;
        const d = new Date(weekStart + 'T00:00:00');
        d.setDate(d.getDate() + (offset * 7));
        const yyyy = d.getFullYear();
        const mm = String(d.getMonth() + 1).padStart(2, '0');
        const dd = String(d.getDate()).padStart(2, '0');
        this.setState({ weekStart: `${yyyy}-${mm}-${dd}` }, () => this.fetchWeekData());
    }

    onGoToCurrentWeek = () => {
        this.setState({ weekStart: getMonday(getTodayDate()) }, () => this.fetchWeekData());
    }

    onSubProgramChange = (choice) => {
        this.setState({ selectedSubProgramId: choice ? choice.value : '' });
    }

    onProgramTypeFilterChange = (e) => {
        const value = e.target.value;
        localStorage.setItem('heatmapTypeFilter', value);
        this.setState({ programTypeFilter: value });
    }

    getFilteredSubPrograms = () => {
        const { subPrograms, programs, programTypeFilter } = this.state;
        if (!programTypeFilter) return subPrograms;
        const programIds = new Set(programs.filter(p => p.type === programTypeFilter).map(p => p.id));
        return subPrograms.filter(sp => programIds.has(sp.programId));
    }

    getSubProgramDisplay = (sp) => {
        const prog = this.state.programs.find(p => p.id === sp.programId);
        if (prog) return `${prog.name} | ${sp.name} (${prog.type})`;
        return sp.name;
    }

    /**
     * Build heatmap data: 24 hours x 7 days
     * Each cell = total minutes logged in that hour slot on that day for the selected sub-program.
     */
    buildHeatmapData = () => {
        const { weekStart, weekData, selectedSubProgramId } = this.state;
        const weekDates = getWeekDates(weekStart);

        // 24 rows (hours) x 7 columns (days)
        const grid = Array.from({ length: 24 }, () => Array(7).fill(0));

        weekDates.forEach((date, dayIndex) => {
            const logs = weekData[date] || [];
            const filtered = selectedSubProgramId
                ? logs.filter(log => String(log.subProgramId) === selectedSubProgramId)
                : logs;

            filtered.forEach(log => {
                if (!log.startTime || !log.endTime) return;
                const startHour = parseInt(log.startTime.substring(0, 2));
                const startMin = parseInt(log.startTime.substring(2));
                const endHour = parseInt(log.endTime.substring(0, 2));
                const endMin = parseInt(log.endTime.substring(2));

                let startTotal = startHour * 60 + startMin;
                let endTotal = endHour * 60 + endMin;
                if (endTotal <= startTotal) endTotal += 24 * 60; // crosses midnight

                // Distribute minutes to each hour slot
                for (let h = 0; h < 24; h++) {
                    const slotStart = h * 60;
                    const slotEnd = (h + 1) * 60;
                    const overlapStart = Math.max(startTotal, slotStart);
                    const overlapEnd = Math.min(endTotal, slotEnd);
                    if (overlapEnd > overlapStart) {
                        grid[h][dayIndex] += (overlapEnd - overlapStart);
                    }
                }
            });
        });

        return grid;
    }

    getHeatColor = (minutes) => {
        if (minutes === 0) return { bg: '#f7fafc', text: '#cbd5e0' };
        if (minutes <= 15) return { bg: 'rgba(102, 126, 234, 0.15)', text: '#667eea' };
        if (minutes <= 30) return { bg: 'rgba(102, 126, 234, 0.30)', text: '#5a67d8' };
        if (minutes <= 45) return { bg: 'rgba(102, 126, 234, 0.50)', text: '#4c51bf' };
        return { bg: 'rgba(102, 126, 234, 0.75)', text: '#ffffff' };
    }

    computeDaySummary = () => {
        const { weekStart, weekData, selectedSubProgramId } = this.state;
        const weekDates = getWeekDates(weekStart);

        return weekDates.map(date => {
            const logs = weekData[date] || [];
            const filtered = selectedSubProgramId
                ? logs.filter(log => String(log.subProgramId) === selectedSubProgramId)
                : logs;

            const totalMinutes = filtered.reduce((sum, log) => {
                if (!log.startTime || !log.endTime) return sum;
                const startMin = parseInt(log.startTime.substring(0, 2)) * 60 + parseInt(log.startTime.substring(2));
                const endMin = parseInt(log.endTime.substring(0, 2)) * 60 + parseInt(log.endTime.substring(2));
                let diff = endMin - startMin;
                if (diff <= 0) diff += 24 * 60;
                return sum + diff;
            }, 0);

            return { date, totalMinutes, logCount: filtered.length };
        });
    }

    render() {
        const { isLoaded, isLoadingWeek, error, weekStart, selectedSubProgramId, programTypeFilter } = this.state;
        const weekDates = getWeekDates(weekStart);
        const filteredSubPrograms = this.getFilteredSubPrograms();

        const styles = {
            page: {
                background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                minHeight: '100vh',
                padding: '30px 0',
            },
            header: {
                background: 'rgba(255, 255, 255, 0.95)',
                backdropFilter: 'blur(10px)',
                borderRadius: '16px',
                padding: '28px 32px',
                marginBottom: '24px',
                boxShadow: '0 10px 40px rgba(0, 0, 0, 0.1)',
                border: '1px solid rgba(255, 255, 255, 0.8)',
            },
            title: {
                fontSize: '2em',
                fontWeight: '800',
                background: 'linear-gradient(135deg, #667eea, #764ba2)',
                WebkitBackgroundClip: 'text',
                WebkitTextFillColor: 'transparent',
                margin: 0,
            },
            content: {
                background: 'rgba(255, 255, 255, 0.95)',
                backdropFilter: 'blur(10px)',
                borderRadius: '16px',
                padding: '28px 32px',
                boxShadow: '0 10px 40px rgba(0, 0, 0, 0.1)',
                border: '1px solid rgba(255, 255, 255, 0.8)',
            },
            controls: {
                display: 'flex',
                alignItems: 'center',
                gap: '12px',
                flexWrap: 'wrap',
                marginTop: '16px',
                padding: '16px 20px',
                background: 'linear-gradient(135deg, #f8f9ff, #f0f2ff)',
                borderRadius: '12px',
                border: '1px solid #e8ecff',
                overflow: 'visible',
                position: 'relative',
                zIndex: 10,
            },
            typeSelect: {
                padding: '8px 16px',
                border: '2px solid #e8ecff',
                borderRadius: '8px',
                fontWeight: '500',
                fontSize: '0.9em',
                background: 'white',
                cursor: 'pointer',
            },
        };

        return (
            <div style={styles.page}>
                <CContainer>
                    <CRow className="justify-content-center">
                        <CCol md="12">
                            {/* Header */}
                            <div style={styles.header}>
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '12px' }}>
                                    <h1 style={styles.title}>🗓️ Weekly Activity Heatmap</h1>
                                    <CButton color="light" onClick={() => this.fetchWeekData()} title="Refresh" style={{ borderRadius: '10px', fontWeight: '600', padding: '8px 14px' }}>🔄</CButton>
                                </div>

                                {/* Controls */}
                                <div style={styles.controls}>
                                    {/* Week navigation */}
                                    <CButton size="sm" onClick={() => this.onWeekChange(-1)} style={{ borderRadius: '8px', fontWeight: '700', padding: '6px 12px', background: 'white', border: '2px solid #e8ecff', color: '#667eea' }}>◀</CButton>
                                    <span style={{ fontWeight: '700', color: '#4a5568', fontSize: '0.92em' }}>
                                        {formatDate(weekDates[0])} — {formatDate(weekDates[6])}
                                    </span>
                                    <CButton size="sm" onClick={() => this.onWeekChange(1)} style={{ borderRadius: '8px', fontWeight: '700', padding: '6px 12px', background: 'white', border: '2px solid #e8ecff', color: '#667eea' }}>▶</CButton>
                                    <CButton size="sm" onClick={this.onGoToCurrentWeek} style={{ borderRadius: '8px', fontWeight: '600', padding: '6px 14px', background: 'linear-gradient(135deg, #667eea, #764ba2)', border: 'none', color: 'white' }}>Today</CButton>

                                    <span style={{ margin: '0 8px', color: '#cbd5e0' }}>|</span>

                                    {/* Type filter */}
                                    <select value={programTypeFilter} onChange={this.onProgramTypeFilterChange} style={styles.typeSelect}>
                                        <option value="">All Types</option>
                                        <option value="WORK">🏢 WORK</option>
                                        <option value="PERSONAL">🏠 PERSONAL</option>
                                    </select>

                                    {/* Sub-program selector */}
                                    <div style={{ minWidth: '300px', flex: 1 }}>
                                        <Select
                                            value={filteredSubPrograms.map(sp => ({ value: String(sp.id), label: this.getSubProgramDisplay(sp) })).find(o => o.value === selectedSubProgramId) || null}
                                            onChange={this.onSubProgramChange}
                                            options={filteredSubPrograms.map(sp => ({ value: String(sp.id), label: this.getSubProgramDisplay(sp) }))}
                                            isClearable={true}
                                            placeholder="Filter by sub-program (all if empty)..."
                                            menuPortalTarget={document.body}
                                            styles={{
                                                control: (base) => ({ ...base, borderRadius: '10px', border: '2px solid #e8ecff', minHeight: '38px' }),
                                                menuPortal: (base) => ({ ...base, zIndex: 9999 }),
                                            }}
                                        />
                                    </div>
                                </div>
                            </div>

                            {/* Content */}
                            <div style={styles.content}>
                                {!isLoaded && <Loading />}
                                {isLoaded && error && (
                                    <div style={{ textAlign: 'center', padding: '40px', color: '#e53e3e', background: '#fff5f5', borderRadius: '12px', border: '1px solid #fed7d7' }}>
                                        <p style={{ fontSize: '1.1em', fontWeight: '500' }}>⚠️ Error: {error}</p>
                                    </div>
                                )}
                                {isLoaded && !error && this.renderHeatmap(isLoadingWeek)}
                            </div>
                        </CCol>
                    </CRow>
                </CContainer>
            </div>
        );
    }

    renderHeatmap(isLoadingWeek) {
        const { weekStart } = this.state;
        const weekDates = getWeekDates(weekStart);
        const grid = this.buildHeatmapData();
        const daySummary = this.computeDaySummary();
        const totalWeekMinutes = daySummary.reduce((sum, d) => sum + d.totalMinutes, 0);
        const totalWeekHours = Math.floor(totalWeekMinutes / 60);
        const totalWeekMins = totalWeekMinutes % 60;

        return (
            <div>
                {isLoadingWeek && (
                    <div style={{ textAlign: 'center', padding: '12px', color: '#667eea', fontWeight: '600', fontSize: '0.9em' }}>
                        Loading week data...
                    </div>
                )}

                {/* Week summary */}
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px', padding: '16px 20px', background: 'linear-gradient(135deg, #f8f9ff, #f0f2ff)', borderRadius: '12px', border: '1px solid #e8ecff' }}>
                    <span style={{ fontWeight: '700', color: '#4a5568', fontSize: '0.95em' }}>📊 Week Total</span>
                    <span style={{ fontFamily: 'monospace', fontWeight: '800', fontSize: '1.2em', color: '#667eea' }}>
                        {totalWeekHours}h {totalWeekMins}m
                    </span>
                </div>

                {/* Day summaries */}
                <div style={{ display: 'flex', gap: '8px', marginBottom: '20px', flexWrap: 'wrap' }}>
                    {daySummary.map((d, i) => {
                        const hours = Math.floor(d.totalMinutes / 60);
                        const mins = d.totalMinutes % 60;
                        const isToday = d.date === getTodayDate();
                        return (
                            <div key={d.date} style={{
                                flex: 1,
                                minWidth: '100px',
                                padding: '12px',
                                borderRadius: '10px',
                                background: isToday ? 'linear-gradient(135deg, #667eea, #764ba2)' : '#f7fafc',
                                border: isToday ? 'none' : '1px solid #e2e8f0',
                                textAlign: 'center',
                            }}>
                                <div style={{ fontWeight: '700', fontSize: '0.8em', color: isToday ? 'rgba(255,255,255,0.8)' : '#a0aec0', marginBottom: '4px' }}>{DAY_LABELS[i]}</div>
                                <div style={{ fontWeight: '800', fontSize: '1em', color: isToday ? 'white' : '#2d3748' }}>
                                    {d.totalMinutes > 0 ? `${hours}h ${mins}m` : '—'}
                                </div>
                                <div style={{ fontSize: '0.72em', color: isToday ? 'rgba(255,255,255,0.7)' : '#a0aec0', marginTop: '2px' }}>
                                    {d.logCount} {d.logCount === 1 ? 'log' : 'logs'}
                                </div>
                            </div>
                        );
                    })}
                </div>

                {/* Heatmap grid */}
                <div style={{ borderRadius: '12px', border: '1px solid #e2e8f0', overflow: 'hidden', boxShadow: '0 2px 8px rgba(0,0,0,0.04)' }}>
                    <div style={{ background: 'linear-gradient(135deg, #667eea, #764ba2)', padding: '12px 20px', color: 'white', fontWeight: '700', fontSize: '0.9em' }}>
                        🔥 ACTIVITY HEATMAP (Days x Hours)
                    </div>

                    <div style={{ overflowX: 'auto', WebkitOverflowScrolling: 'touch', padding: '20px' }}>
                        <table style={{ borderCollapse: 'separate', borderSpacing: '3px', margin: '0 auto' }}>
                            <thead>
                                <tr>
                                    <th style={{ width: '60px' }}></th>
                                    {grid[0] && grid.map((_, hourIndex) => {
                                        const label = hourIndex === 0 ? '12A' : hourIndex < 12 ? hourIndex + 'A' : hourIndex === 12 ? '12P' : (hourIndex - 12) + 'P';
                                        return (
                                            <th key={'h-' + hourIndex} style={{
                                                textAlign: 'center',
                                                padding: '4px 2px',
                                                fontSize: '0.68em',
                                                fontWeight: '600',
                                                color: '#a0aec0',
                                                minWidth: '32px',
                                            }}>
                                                {label}
                                            </th>
                                        );
                                    })}
                                </tr>
                            </thead>
                            <tbody>
                                {weekDates.map((date, dayIndex) => {
                                    const isToday = date === getTodayDate();
                                    return (
                                        <tr key={'day-' + dayIndex}>
                                            <td style={{ textAlign: 'right', paddingRight: '10px', fontSize: '0.78em', fontWeight: '700', color: isToday ? '#667eea' : '#4a5568', whiteSpace: 'nowrap' }}>
                                                {DAY_LABELS[dayIndex]} <span style={{ fontSize: '0.85em', color: isToday ? '#667eea' : '#a0aec0', fontWeight: '500' }}>{new Date(date + 'T00:00:00').getDate()}</span>
                                            </td>
                                            {grid.map((row, hourIndex) => {
                                                const minutes = row[dayIndex];
                                                const color = this.getHeatColor(minutes);
                                                const label = hourIndex === 0 ? '12 AM' : hourIndex < 12 ? hourIndex + ' AM' : hourIndex === 12 ? '12 PM' : (hourIndex - 12) + ' PM';
                                                return (
                                                    <td key={hourIndex} title={`${DAY_LABELS[dayIndex]} ${label}: ${minutes} min`} style={{
                                                        minWidth: '32px',
                                                        height: '32px',
                                                        background: color.bg,
                                                        borderRadius: '4px',
                                                        textAlign: 'center',
                                                        fontSize: '0.62em',
                                                        fontWeight: '700',
                                                        color: color.text,
                                                        cursor: 'default',
                                                        border: minutes > 0 ? '1px solid rgba(102, 126, 234, 0.2)' : '1px solid #edf2f7',
                                                    }}>
                                                        {minutes > 0 ? minutes + 'm' : ''}
                                                    </td>
                                                );
                                            })}
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>

                    {/* Legend */}
                    <div style={{ padding: '12px 20px', borderTop: '1px solid #edf2f7', display: 'flex', alignItems: 'center', gap: '12px', justifyContent: 'center' }}>
                        <span style={{ fontSize: '0.78em', color: '#718096', fontWeight: '600' }}>Less</span>
                        {[0, 15, 30, 45, 60].map(min => {
                            const color = this.getHeatColor(min);
                            return (
                                <div key={min} style={{ width: '20px', height: '20px', borderRadius: '4px', background: color.bg, border: '1px solid rgba(102, 126, 234, 0.2)' }} title={min + ' min'} />
                            );
                        })}
                        <span style={{ fontSize: '0.78em', color: '#718096', fontWeight: '600' }}>More</span>
                    </div>
                </div>
            </div>
        );
    }
}

export default WeeklyHeatmap;
